const retention=`
  await t.test('TASK02R controlled retention deletes expired derivatives, preserves lawful/manual rows, rolls back and repeats safely',async()=>{
   const manualBefore=hash(JSON.stringify((await owner.query("SELECT to_jsonb(t) body FROM srm.supplier_locations t WHERE origin='MANUAL' ORDER BY location_id")).rows))
   const selected=(await owner.query("SELECT location_id FROM srm.supplier_locations WHERE location_group='RELATED_ENTITIES' ORDER BY location_id LIMIT 1")).rows[0]
   assert(selected)
   const unexpiredBefore=(await owner.query("SELECT count(*)::int n FROM srm.supplier_locations WHERE location_group='RELATED_ENTITIES'")).rows[0].n
   await owner.query("UPDATE srm.supplier_locations SET retention_until=now()-interval '1 second' WHERE location_id=$1",[selected.location_id])
   await assert.rejects(pool.query('SELECT srm.location_expire_controlled()'),e=>e.code==='42501')
   await owner.query('BEGIN;SET LOCAL ROLE profitia_access_owner')
   try{const r=await owner.query('SELECT srm.location_expire_controlled() value');assert.equal(r.rows[0].value.expiredDerivedLocations,1)}
   finally{await owner.query('ROLLBACK')}
   assert.equal((await owner.query('SELECT count(*)::int n FROM srm.supplier_locations WHERE location_id=$1',[selected.location_id])).rows[0].n,1)
   const receipt=(await controlled(()=>owner.query('SELECT srm.location_expire_controlled() value'))).rows[0].value
   assert.deepEqual(receipt,{expiredCoordinates:0,expiredDerivedLocations:1})
   assert.deepEqual((await controlled(()=>owner.query('SELECT srm.location_expire_controlled() value'))).rows[0].value,{expiredCoordinates:0,expiredDerivedLocations:0})
   assert.equal((await owner.query("SELECT count(*)::int n FROM srm.supplier_locations WHERE location_group='RELATED_ENTITIES'")).rows[0].n,unexpiredBefore-1)
   assert.equal(hash(JSON.stringify((await owner.query("SELECT to_jsonb(t) body FROM srm.supplier_locations t WHERE origin='MANUAL' ORDER BY location_id")).rows)),manualBefore)
   console.log('TASK02R_RETENTION_RECEIPT '+JSON.stringify({scope:'ISOLATED_ONLY',...receipt,manualUnchanged:true,nonexpiredUnchanged:true,rollback:true,idempotent:true}))
  })
`;
